// Default entity logo used when the project supplies none ("الجهة الرقمية — خدمات ذكية" / "Digital Entity — Smart Services").
// Supplied by the toolkit owner (Ahmed Darwish) for this purpose. Transparent artwork at 2× inside an SVG whose intrinsic size is the
// Figma Logo Placeholder Medium content box (48 px high), because dga-nav-header-logos renders the image at its intrinsic size.
// Embedded as data URIs so React, Angular, vanilla and ArcGIS Experience Builder use it without bundler asset rules.
// Replace it through the site configuration (identity.logo) — never by editing this file in a project.
export const DEFAULT_LOGO_AR = 'data:image/svg+xml;base64,';
export const DEFAULT_LOGO_EN = 'data:image/svg+xml;base64,';
export const DEFAULT_LOGO_SIZE = Object.freeze({ ar: { width: 160, height: 48 }, en: { width: 160, height: 48 } });
